/* Boost APFC: a voltage PI sets the input-current amplitude g (A/V),
   the inductor current follows g*|v_ac| inside a +/- band, checked once per sample.
   Ts = 5 us (code.fs = 200 kHz). Retune kp, ki, band and the limits for another power stage. */
const double Ts = 5e-6, kp = 2.4e-4, ki = 3e-3, gmax = 0.05, band = 0.3;
double e = reference - voltage;
double g = fmin(fmax(kp*e + integral, 0.0), gmax);
next_integral = fmin(fmax(integral + ki*Ts*e, 0.0), gmax);
double iref = g*rectified;
if (current < iref - band) next_on = 1.0;
else if (current > iref + band) next_on = 0.0;
gate = next_on;
